mapper.select:
SELECT id, article_id, user_id, parent_id, reply_to_user_id, content, like_count, deleted, create_time, update_time
FROM (SELECT c.*, ROW_NUMBER() OVER (PARTITION BY parent_id ORDER BY create_time, id) AS rn
      FROM comment c
      WHERE c.deleted = 0 AND c.parent_id IN
      #{id}
     ) t
WHERE t.rn <= #{n}
ORDER BY parent_id, create_time, id
